    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        seg=t[m.end():]
        rows=[]
        while len(rows)<h and '\n' in seg:
            row=seg.split('\n')[0]
            if all(x.isdigit() for x in row.split()):
                rows.append([int(x) for x in row.split()])
            else: break
            seg=''.join(seg.split('\n')[1:])
        if k not in G and len(rows)==h:
            G[k]=rows
    return G
G=load(); print(sorted(G))
def setup(nm,I,O):
    Sr,Si=[(r,c) for r in range(11) for c in range(11) if I[r][c]==3][0]
    F=set((r,c) for r in range(11) for c in range(11) if O[r][c]==3)
    Tw=list((a,b) for a in range(11) for b in range(11) if I[a][b]==2)
    return Sr,Si,F,Tw
Sdata={k:setup('Demo pair %s'%i,G['Demo pair %s input'%i],G['Demo pair %s output'%i]) for i in (1,2,3)}
for nm,(Sr,Si,F,Tw) in Sdata.items():
    miss=[]
    for r in range(11):
        for c in range(11):
            if (r,c) in [tw[:2] for tw in Tw]: continue
            dseed=abs(r-Sr)+abs(c-Si)
            dobs=min(abs(r-a)+abs(c-b) for a,b in Tw)
            pred=dseed<dobs
            stat='F' if (r,c) in F else 'E'
            if pred!=stat=='F': miss.append(((r-Sr,c-Si),stat,dseed,dobs))
    print(nm,'seed',(Sr,Si),'miss:',len(miss),miss[:8])

