def solve(I,mode='step'):
    Hh,Ww=len(I),len(I[0])
    Sr,Si=[(r,c) for r in range(Hh) for c in range(Ww) if I[r][c]==3][0]
    out=[[I[r][c] for c in range(Ww)] for r in range(Hh)]
    # BFS from seed over empty cells, 8-conn, fill visited cells whose stepcount is even
    from collections import deque
    q=deque([(Sr,Si,0)])
