def get_feat(I,a,b,Sr,Si,H,W):
    dr=a-Sr; dc=b-Si; ds=max(abs(dr),abs(dc)); man=abs(dr)+abs(dc); sm=(dr+dc)%2
    def rayhit(d_r,d_c):
        rr,cc=a+d_r,b+d_c; n=1; hit=None
        while 0<=rr<H and 0<=cc<W:
            if I[rr][cc]==2: hit=n; break
            rr+=d_r; cc+=d_c; n+=1
        return hit
